"""Wallet service: top-ups and spends on a customer's wallet."""
import psycopg


class InsufficientFunds(Exception):
    pass


def _read_balance(conn: psycopg.Connection, account_id: int) -> int:
    row = conn.execute("SELECT balance FROM accounts WHERE id = %s", (account_id,)).fetchone()
    if row is None:
        raise ValueError("unknown account")
    return row[0]


def deposit(conn: psycopg.Connection, account_id: int, amount: int) -> None:
    with conn.transaction():
        row = conn.execute(
            "UPDATE accounts SET balance = balance + %s WHERE id = %s RETURNING balance",
            (amount, account_id),
        ).fetchone()
        if row is None:
            raise ValueError("unknown account")


def withdraw(conn: psycopg.Connection, account_id: int, amount: int) -> None:
    with conn.transaction():
        row = conn.execute(
            "UPDATE accounts SET balance = balance - %s "
            "WHERE id = %s AND balance >= %s RETURNING balance",
            (amount, account_id, amount),
        ).fetchone()
        if row is None:
            # A withdraw never removes the account, so a missing row means
            # the account does not exist; anything else is insufficient funds.
            exists = conn.execute(
                "SELECT EXISTS(SELECT 1 FROM accounts WHERE id = %s)", (account_id,)
            ).fetchone()[0]
            if not exists:
                raise ValueError("unknown account")
            raise InsufficientFunds(account_id)
